for zh in [False,True]:
 d=R/'zh' if zh else R;pre='../' if zh else './';film='../../?lang=zh' if zh else '../?lang=en'; t=lambda en,cn:cn if zh else en
 mark='<svg xmlns="http://www.w3.org/2000/svg" class="insights-mark" viewBox="0 0 64 48" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="butt" stroke-linejoin="round" aria-hidden="true"><path d="M29 10C22-1 4 3 4 24S22 49 29 38M38 45V4H46C64 4 64 27 46 27H38"/><circle cx="60" cy="42" r="2.6" fill="currentColor" stroke="none"/></svg>'
 def pic(n,alt):return f'<img src="{pre}media/{n}.webp" alt="{alt}" width="1440" height="900" loading="lazy">'
 h=f'''<!doctype html><html lang="{'zh-CN' if zh else 'en'}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>{t('What Stays · Creative Practice','里面有人 · 创作实践')}</title><link rel="preload" href="{pre}fonts/manrope.woff" as="font" type="font/woff" crossorigin><link rel="stylesheet" href="{pre}style.css"><body><a class="skip" href="#main">{t('Skip to content','跳至正文')}</a><div class="site"><header class="top" id="top"><a class="brand" href="{'.' if zh else './'}" aria-label="Creative Practice">{mark}<span class="brand-divider" aria-hidden="true"></span><span class="brand-wordmark"><span>Creative</span><span>Practice</span></span></a><nav class="languages" aria-label="Language"><a href="{ '../' if zh else './'}" lang="en" {'aria-current="page"' if not zh else ''}>English</a><a href="{'./' if zh else 'zh/'}" lang="zh-CN" {'aria-current="page"' if zh else ''}>中文</a></nav></header><main id="main"><section class="hero"><div><span class="meta">{t('Creative Practice / Interactive narrative','创作实践 / 原创互动叙事')}</span><h1>{t('What Stays','里面有人')}</h1><p class="project-type">{t('From personal writing to an interactive visual essay.','从个人写作，到交互影像随笔。')}</p></div><div><p class="lede">{t('An adaptation of my own fiction, told through subtitles, silhouettes and sound. At a few moments, the reader makes a small gesture to carry the story forward.','我把自己的小说改编成一部可以观看、聆听和动手参与的作品。文字通过字幕、剪影画面和声音展开；在少数节点上，观众用自己的动作推进故事。')}</p><div class="actions"><a class="action primary" href="{film}">{t('Experience Act I','开始体验第一幕')} <span aria-hidden="true">↗</span></a><a class="action" href="#decisions">{t('Explore the process','了解制作过程')} <span aria-hidden="true">↓</span></a></div></div></section><figure class="hero-art">{pic('hero',t('A figure and a fading reflection in a cold blue window.','冷蓝色窗前的女主与逐渐消散的倒影。'))}<figcaption><span>{t('ACT I / A PLACE LEFT EMPTY','第一幕 / 空出来的位置')}</span><span>{t('An original interactive visual essay','原创交互影像随笔')}</span></figcaption></figure><div class="facts"><dl><dt>{t('My role','我的角色')}</dt><dd>{t('Original writing · Narrative & interaction direction · Review & iteration decisions','原创写作 · 叙事与交互方向 · 试看与迭代决策')}</dd></dl><dl><dt>{t('Working with AI','协作方式')}</dt><dd>{t('Codex-assisted prototyping, implementation and refinement','通过 Codex 协作实现原型、调试与迭代')}</dd></dl><dl><dt>{t('Current scope','当前进展')}</dt><dd>{t('Act I live · Chinese & English<br>Further acts in development','第一幕已上线 · 中英文版本<br>其余章节待续')}</dd></dl></div>
<section class="section" id="background"><div class="section-head"><span class="meta">{t('01 / Starting point','01 / 创作起点')}</span><div><h2>{t('Another way to read a story.','让文字拥有另一种被阅读的方式。')}</h2><div class="prose"><p>{t('Writing is part of my everyday life. I wanted to explore what happens when a story is experienced through images, pauses and sound—and when a reader occasionally has to do something to continue.','写作是我生活的一部分。我想试试，同一个故事在被观看、聆听，以及需要读者亲手完成一点什么时，会产生怎样的体验。')}</p><p>{t('The project began with my fiction. As it took shape, I directed the silhouette style, the order and timing of subtitles, and the moments where sound or interaction could carry the narrative. Reviewing the actual prototype helped me see where the experience departed from the intention.','这个项目从我的小说出发。我逐步确定剪影的视觉方向、字幕的节奏、声音的出现与离开，以及观众参与的位置。实际试看让我发现：文字中成立的衔接，变成画面后未必仍然连贯。')}</p></div><div class="jump"><a href="#decisions">{t('Design decisions','关键设计决策')}</a><a href="#collaboration">{t('My working process','我的协作方式')}</a><a href="#tools">{t('Tools & responsibilities','工具与分工')}</a></div></div></div></section>
<section class="section" id="decisions"><div class="section-head"><span class="meta">{t('02 / Decisions','02 / 关键决策')}</span><div><h2>{t('Making the experience match the intention.','把体验意图，落到具体的设计决定里。')}</h2><p class="prose">{t('Two decisions show how reviewing the prototype changed the design. These are observations from my own reviews, supported by the implemented versions.','下面两次调整，展示了我如何通过试看识别问题，再把感受转化为可以实现和检查的修改要求。')}</p></div></div><article class="case"><div class="case-top"><span class="case-count">{t('DECISION 01','决策 01')}</span><div><h3>{t('Let the interaction follow the character.','让交互延续人物正在做的事。')}</h3><p class="prose">{t('The characters were packing their desks in a classroom, but an earlier version returned to a bus window for a reflection-dragging interaction. During review, I found that this broke the continuity of the scene.','两个人正在教室里各自收拾桌面，早期版本却切回车窗，让观众拖动反光完成转场。试看时，我发现这个操作切断了正在发生的事。')}</p></div></div><div class="pair"><figure>{pic('window-before',t('Earlier prototype: the view returns to a bus window.','早期原型：回到车窗的场景。'))}<figcaption><b>{t('Earlier prototype / The window','早期版本 / 推动车窗反光')}</b>{t('An action separated from the classroom scene.','操作离开了正在发生的教室场景。')}</figcaption></figure><figure><a class="media-link" href="{pre}media/notebook-interaction.mp4">{pic('notebook',t('Current version: hands beside an open notebook on the desk.','当前版本：女主双手与桌上未合拢的笔记本。'))}<span>{t('Watch interaction (silent) ↗','查看无声交互演示 ↗')}</span></a><figcaption><b>{t('Current version / Close the notebook','当前版本 / 合上笔记本')}</b>{t('The reader completes an action the character has already begun.','观众完成女主收拾桌面时已经开始的动作。')}</figcaption></figure></div><div class="decision"><div><h4>{t('My decision','我的判断与决定')}</h4><p>{t('Keep the interaction in the classroom. Follow her hands towards the notebook and make closing its cover the transition.','把交互留在同一间教室，沿女主的动作推近笔记本，将合上封面作为这一段的结束。')}</p></div><div><h4>{t('What was implemented','具体实现')}</h4><p>{t('An incomplete drag returns gently. Closing the cover triggers a paper sound, a quiet transition and the next line. The gesture is available in the live first act.','拖动未到位时，封面轻轻弹回；合上后，纸封轻响，底声收掉，再通过短暗场和字幕衔接后续画面。正式第一幕中已可体验。')}</p></div></div></article>
<article class="case"><div class="case-top"><span class="case-count">{t('DECISION 02','决策 02')}</span><div><h3>{t('Design the music’s departure, too.','音乐离开的时候，也需要设计。')}</h3><p class="prose">{t('I wanted the phone scene to become quiet, so music returning during the ballroom memory would matter. The shop-exit fade initially felt abrupt. Extending silence alone had not solved the broader musical experience.','我希望看手机时观众能静下来，为舞会触颈处音乐的重新进入留出空间。但便利店的音乐退场显得突兀；此前单纯扩大静音区域的方案，也没有达到我想要的效果。')}</p></div></div><div class="sound"><div class="sound-grid"><figure>{pic('dinner',t('The everyday dinner scene.','日常的饭桌场景。'))}<span class="sound-step">{t('01 / EVERYDAY LIFE','01 / 日常')}</span><h4>Reverie</h4><p>{t('A continuous musical cue accompanies daily life, then gradually withdraws as she leaves the shop.','用连续发展的音乐陪伴日常，在她准备离店时逐渐退下。')}</p></figure><figure>{pic('phone',t('The phone outside the shop.','出店后查看手机。'))}<span class="sound-step">{t('02 / A QUIET INTERVAL','02 / 安静的间隙')}</span><h4>{t('Room for the world','让环境声接住')}</h4><p>{t('The fade lasts about 5.8 seconds. Footsteps, the door and ambience carry the exit; the phone close-up has no score.','退场拉长到约 5.8 秒，由脚步、开门和环境声承接；手机特写保持无配乐。')}</p></figure><figure>{pic('ballroom',t('The ballroom memory.','毕业舞会的回忆。'))}<span class="sound-step">{t('03 / THE MEMORY','03 / 回忆')}</span><h4>Moonlight</h4><p>{t('A contrasting cue enters at the neck-touch, giving the memory its own emotional temperature.','在手触碰脖子的节点进入，让回忆拥有不同的听觉温度。')}</p></figure></div><p class="sound-note">{t('Cue structure illustrated above. Music: Scott Buckley · CC BY 4.0 · Excerpts edited with fades and level changes.','以上为声音结构示意。配乐：Scott Buckley · CC BY 4.0 · 使用经剪辑、淡入淡出及音量调整的录音片段。')}</p></div><div class="decision"><div><h4>{t('My decision','我的判断与决定')}</h4><p>{t('Choose recorded music with clear permission, audition it with the scenes, and make ambience connect the quiet interval to the musical return.','选择许可明确的成品音乐，结合画面试听，并让环境声连接安静段落与后面的音乐入点。')}</p></div><div><h4>{t('What was implemented','具体实现')}</h4><p>{t('Codex assisted with sourcing, audio edits and playback checks. I reviewed the results and decided on the cues, timing and transition changes.','Codex 协助查找资源、处理音频与检查播放；我通过试听决定选曲、入点及退场调整。')}</p></div></div></article></section>
<section class="section" id="collaboration"><div class="section-head"><span class="meta">{t('03 / Collaboration','03 / 协作与迭代')}</span><div><h2>{t('Turn a reaction into an actionable requirement.','把“不太对”，变成可执行的修改要求。')}</h2><div class="prose"><p>{t('Reviews surfaced concrete issues: awkward arms, objects left behind after being picked up, and actions and sounds happening at different times. I pointed to the specific frame or moment, described the intended behaviour, and asked for similar scenes to be checked.','试看中出现过手臂姿态不自然、物品拿走后仍留在原处，以及动作和声音不同步等问题。我通过具体画面和时间点指出偏差，描述期望的行为，并要求检查其他场景是否也有类似问题。')}</p><p>{t('I directed the experience and made acceptance decisions; Codex handled the code, audio processing and deployment operations. The process documented here is my own prototype review, rather than a study with external users.','我负责体验方向、反馈和取舍，Codex 执行代码实现、音频处理及部署操作。这里记录的是作者试看与协作迭代，目前未进行外部用户研究。')}</p></div></div></div><div class="process">'''
 steps=[('01',t('Describe','提出要求'),t('Name the scene, intention and expected behaviour.','指出场景、表达意图及期望行为。')),('02',t('Prototype','形成预览'),t('Use Codex to implement a concrete version to review.','借助 Codex 将要求变成可检查的版本。')),('03',t('Review','试看与取舍'),t('Check the actual movement, pace, visual style and sound.','结合实际动作、节奏、画风和声音判断效果。')),('04',t('Verify','检查与交付'),t('Review changes, then check the published experience.','检查修改，再核对上线后的实际体验。'))]
 for n,title,body in steps:h+=f'<div><b>{n}</b><h4>{title}</h4><p>{body}</p></div>'
 h+='</div></section>'
 h+=f'<section class="section" id="tools"><div class="section-head"><span class="meta">{t("04 / Tools & roles","04 / 工具与分工")}</span><div><h2>{t("A clear role for each tool.","工具如何参与，分工写清楚。")}</h2><p class="prose">{t("Codex was my primary collaboration tool. The technologies below were used in the implementation; my contribution was to define the experience, judge the results and guide iteration.","Codex 是我推进制作时使用的主要协作工具。下列技术用于具体实现；我通过明确体验要求、评估预览和决定修改来推动项目。")}</p></div></div><div class="tools">'
 rows=[('Codex',t('Assisted prototyping, code changes, debugging and delivery.','协作实现原型、修改代码、调试与交付。'),t('I gave concrete requirements, reviewed previews and made design and acceptance decisions.','我提出具体要求、检查预览，并作设计与验收判断。')),('HTML / CSS',t('Page structure, bilingual typography, full-screen layout and interface transitions.','页面结构、中英文排版、整屏布局及界面转场。'),t('Codex wrote the implementation; I reviewed presentation and behaviour.','Codex 编写实现；我检查呈现与使用体验。')),('JavaScript / Canvas',t('Programmatically drawn silhouettes, scenes, animation, subtitle timing and notebook dragging.','用代码绘制剪影与场景，实现动画、字幕时序和拖动合书。'),t('I defined and refined narrative and interaction requirements; Codex implemented them.','我定义并调整叙事和交互要求；Codex 实现。')),('Web Audio API / FFmpeg',t('Foley, playback synchronisation, audio edits, fades and pitch-preserving speed variants.','拟音、播放同步、音频剪辑、淡入淡出及保持音高的倍速版本。'),t('Codex handled audio processing; I auditioned and directed the sound.','Codex 操作处理；我试听并决定声音方向。')),('Git / GitHub Pages',t('Version history, isolated branches and publishing at an independent portfolio address.','版本记录、独立分支，以及作品集内独立地址的网页发布。'),t('Codex operated version control and deployment. I set requirements and reviewed delivery.','Codex 执行版本管理与部署；我提出要求并检查交付。')),('Playwright / Chromium',t('Browser checks for language, timing, interaction, layout and audio signals; actual screenshots.','检查语言、时序、交互、布局和音频信号，并生成实际截图。'),t('Codex ran implementation checks; these were not external user tests.','Codex 执行实现检查；这些检查不等同于外部用户测试。'))]
 for name,use,role in rows:h+=f'<div class="tool"><h3>{name}</h3><p><b>{t("Used for","实际用途")}</b>{use}</p><p><b>{t("Responsibilities","参与与分工")}</b>{role}</p></div>'
 h+=f'''</div><p class="tool-note">{t('Canvas is the browser drawing technology used for the artwork. The list documents how the tools supported the project and who handled each part.','Canvas 是作品使用的浏览器绘图技术。以上清单记录各项工具在制作中的具体用途与协作分工。')}</p></section><section class="closing"><div><span class="meta">{t('An ongoing creative practice','持续发展的创作实践')}</span><h2>{t('The first chapter is ready.','先从第一幕开始。')}</h2><p>{t('Act I is live in Chinese and English, with subtitles, music, ambience and interaction. Later acts remain in development. No recorded voiceover is currently included.','第一幕已提供中英文体验，包含字幕、配乐、环境音和交互。目前没有录制旁白，其余章节仍待续。')}</p></div><div class="actions"><a class="action primary" href="{film}">{t('Experience Act I','开始体验第一幕')} <span aria-hidden="true">↗</span></a><a class="action" href="#top">{t('Back to top','返回顶部')} ↑</a></div></section><footer class="credits">Music: “Reverie” &amp; “Moonlight” by <a href="https://www.scottbuckley.com.au/">Scott Buckley</a> · <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>.<br>{t('Edited excerpts with fades and level changes.','录音片段经过裁切、淡入淡出及音量调整。')} <a href="{'../../../' if zh else '../../'}licensed-score/sources.json">{t('Source & editing records','来源与剪辑记录')}</a><br>{t('Images and the interaction demonstration are captured from implemented prototype versions.','页面画面及交互演示均采自实际实现的原型版本。')}</footer></main></div></body></html>'''
 # Both language entries resolve resources relative to their actual directory depth.
 h=h.replace('../../../licensed-score/sources.json','../../licensed-score/sources.json').replace('../../licensed-score/sources.json','../../licensed-score/sources.json') if zh else h.replace('../../licensed-score/sources.json','../licensed-score/sources.json')
 (d/'index.html').write_text(h)
print('Bilingual portfolio introduction generated')
